import { dedent } from "@luxass/utils";

type ReleaseMetadataValue = string | number | boolean | null;

type ReleaseMetadataRecord = Record<string, ReleaseMetadataValue>;

interface GenerationInput {
  currentDraftVersion: string;
  latestStableVersion: string;
}

const GENERATED_FILE_HEADER = dedent`
  /**
   * This file is auto-generated by scripts/generate-constants.ts
   * Do not edit it manually.
   * To regenerate, run the script with:
   *  pnpm --filter @unicode-utils/metadata generate:constants
   */
`;

const PROPERTY_DOCS: Record<string, string> = {
  version: 'The Unicode version number.\nFor example, "17.0.0".',
  documentationUrl: "The URL to the official Unicode documentation for this version.",
  date: "The release date of this version.",
  url: "The URL to the official Unicode data files for this version.",
  mappedUcdVersion: "The mapped UCD version for this Unicode version, if any.",
  type: "The stability type of this version.",
};

interface InterfaceProperty {
  comment?: string;
  hasNull: boolean;
  types: Set<string>;
}

function formatValue(value: ReleaseMetadataRecord[string]): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  return String(value);
}

function collectInterfaceProperties(releases: ReleaseMetadataRecord[]) {
  const propertyOrder: string[] = [];
  const interfaceProperties = new Map<string, InterfaceProperty>();

  for (const release of releases) {
    for (const [key, value] of Object.entries(release)) {
      if (!interfaceProperties.has(key)) {
        interfaceProperties.set(key, {
          comment: PROPERTY_DOCS[key],
          hasNull: false,
          types: new Set(),
        });
        propertyOrder.push(key);
      }

      const property = interfaceProperties.get(key)!;

      if (value == null) {
        property.hasNull = true;
        continue;
      }

      if (typeof value === "string") {
        if (key === "type") {
          property.types.add(`"${value}"`);
          property.types.add('"draft"');
          property.types.add('"stable"');
          continue;
        }

        property.types.add("string");
        continue;
      }

      property.types.add(typeof value);
    }
  }

  return propertyOrder.map((key) => [key, interfaceProperties.get(key)!] as const);
}

function renderInterfaceProperties(releases: ReleaseMetadataRecord[]): string {
  return collectInterfaceProperties(releases)
    .map(([key, { comment, hasNull, types }]) => {
      const typeString = Array.from(types).join(" | ");
      const fullType = hasNull ? `${typeString} | null` : typeString;
      const commentBlock = comment
        ? `/**\n     * ${comment.split("\n").join("\n     * ")}\n     */\n    `
        : "";

      return `${commentBlock}${key}: ${fullType};`;
    })
    .join("\n\n    ");
}

function renderReleaseRecord(release: ReleaseMetadataRecord): string {
  const properties = Object.entries(release)
    .map(([key, value]) => `${key}: ${formatValue(value)}`)
    .join(", ");

  return `{ ${properties} }`;
}

export function renderUnicodeVersionConstants(input: GenerationInput): string {
  return dedent`
    ${GENERATED_FILE_HEADER}

    export const UNICODE_DRAFT_VERSION = ${JSON.stringify(input.currentDraftVersion)} as const;

    export const UNICODE_STABLE_VERSION = ${JSON.stringify(input.latestStableVersion)} as const;
  `;
}

export function renderUnicodeVersionMetadata(releases: ReleaseMetadataRecord[]): string {
  const interfaceProperties = renderInterfaceProperties(releases);
  const metadataEntries = releases.map(renderReleaseRecord).join(",\n  ");

  return dedent`
    ${GENERATED_FILE_HEADER}

    export const UNICODE_VERSION_METADATA: UnicodeVersionMetadata[] = [
      ${metadataEntries}
    ];

    export interface UnicodeVersionMetadata {
      ${interfaceProperties}
    }
  `;
}
